const { Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType, BorderStyle } = require('docx');
const fs = require('fs');

async function generateResume() {
    const doc = new Document({
        sections: [{
            properties: {
                page: {
                    margin: {
                        top: 720,
                        right: 720,
                        bottom: 720,
                        left: 720
                    }
                }
            },
            children: [
                // Header - Name
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "Varun Ramesh",
                            bold: true,
                            size: 32,
                            font: "Calibri"
                        })
                    ],
                    alignment: AlignmentType.CENTER,
                    spacing: { after: 100 }
                }),

                // Contact Info
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "Bellingham, WA • varun.ramesh08@gmail.com • linkedin.com/in/vramesh16",
                            size: 22,
                            font: "Calibri"
                        })
                    ],
                    alignment: AlignmentType.CENTER,
                    spacing: { after: 200 }
                }),

                // Divider
                new Paragraph({
                    border: {
                        bottom: { style: BorderStyle.SINGLE, size: 6, color: "000000" }
                    },
                    spacing: { after: 200 }
                }),

                // Professional Summary Header
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "Professional Summary",
                            bold: true,
                            size: 24,
                            font: "Calibri"
                        })
                    ],
                    spacing: { before: 100, after: 100 }
                }),

                // Summary Text
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "Technical Program Manager with 8+ years leading infrastructure launches and cross-functional programs at hyperscale. Proven track record orchestrating end-to-end launches across compute, networking, storage, and AI platform teams—from Go/No-Go frameworks to operational playbooks. Deep experience with AI infrastructure operations including tier-1 workloads (OpenAI, NVIDIA, Databricks). Expert in building scalable processes, navigating tradeoffs under pressure, and earning trust through technical depth and crisp execution.",
                            size: 22,
                            font: "Calibri"
                        })
                    ],
                    spacing: { after: 200 }
                }),

                // Divider
                new Paragraph({
                    border: {
                        bottom: { style: BorderStyle.SINGLE, size: 6, color: "000000" }
                    },
                    spacing: { after: 200 }
                }),

                // Key Skills Header
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "Key Skills",
                            bold: true,
                            size: 24,
                            font: "Calibri"
                        })
                    ],
                    spacing: { before: 100, after: 100 }
                }),

                // Skills - Launch & Program Management
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "Launch & Program Management: ",
                            bold: true,
                            size: 22,
                            font: "Calibri"
                        }),
                        new TextRun({
                            text: "End-to-end launch ownership • Go/No-Go decision frameworks • Cross-functional orchestration • Risk & dependency tracking • Stakeholder communication • Process scalability",
                            size: 22,
                            font: "Calibri"
                        })
                    ],
                    spacing: { after: 80 }
                }),

                // Skills - Infrastructure & AI
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "Infrastructure & AI Platforms: ",
                            bold: true,
                            size: 22,
                            font: "Calibri"
                        }),
                        new TextRun({
                            text: "Cloud infrastructure (Compute, Storage, Networking) • AI/ML workload operations • GPU cluster provisioning • Distributed systems • Performance optimization • Telemetry & observability",
                            size: 22,
                            font: "Calibri"
                        })
                    ],
                    spacing: { after: 80 }
                }),

                // Skills - Leadership
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "Leadership & Execution: ",
                            bold: true,
                            size: 22,
                            font: "Calibri"
                        }),
                        new TextRun({
                            text: "Influence without authority • Operational playbook development • Executive communication • Decision-making under pressure • Technical troubleshooting",
                            size: 22,
                            font: "Calibri"
                        })
                    ],
                    spacing: { after: 200 }
                }),

                // Divider
                new Paragraph({
                    border: {
                        bottom: { style: BorderStyle.SINGLE, size: 6, color: "000000" }
                    },
                    spacing: { after: 200 }
                }),

                // Professional Experience Header
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "Professional Experience",
                            bold: true,
                            size: 24,
                            font: "Calibri"
                        })
                    ],
                    spacing: { before: 100, after: 150 }
                }),

                // Role 1 Title
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "Senior Technical Program Manager, Infrastructure Engineering",
                            bold: true,
                            size: 22,
                            font: "Calibri"
                        })
                    ],
                    spacing: { after: 40 }
                }),

                // Role 1 Company
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "Microsoft, Azure Compute | Redmond, WA | 2022 – Present",
                            italics: true,
                            size: 22,
                            font: "Calibri"
                        })
                    ],
                    spacing: { after: 80 }
                }),

                // Role 1 Description
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "Lead infrastructure launches and cross-functional programs for Azure's core platform, coordinating across Compute, Networking, Storage, and AI infrastructure teams serving enterprise customers worldwide.",
                            size: 22,
                            font: "Calibri"
                        })
                    ],
                    spacing: { after: 80 }
                }),

                // Bullet 1
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "• Led industry-first money-back latency SLA launch for Azure Kubernetes Service (<122ms target, 100 nodes, global coverage), orchestrating cross-functional teams across AKS, Kubernetes, Compute, Storage, and Networking; owned Go/No-Go decision framework, testing criteria, and regression detection, achieving 99.9% SLA performance announced at Microsoft Ignite",
                            size: 22,
                            font: "Calibri"
                        })
                    ],
                    spacing: { after: 60 }
                }),

                // Bullet 2
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "• Established reusable launch framework for 6 generations of Azure SKU releases (ARM64, Azure Boost, GPU instances), defining testing criteria, performance thresholds, and Go/No-Go decision gates; drove global launches across Azure regions exceeding all performance targets",
                            size: 22,
                            font: "Calibri"
                        })
                    ],
                    spacing: { after: 60 }
                }),

                // Bullet 3
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "• Orchestrated cross-team infrastructure programs managing dependencies across Compute, Networking, and Storage teams, achieving 17x latency reduction for large-scale cluster provisioning and retaining $3M/month enterprise workload vs. competitor migration",
                            size: 22,
                            font: "Calibri"
                        })
                    ],
                    spacing: { after: 60 }
                }),

                // Bullet 4
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "• Operational lead for tier-1 AI infrastructure (OpenAI/NVIDIA, Databricks, Snowflake); reduced mean time to mitigation from 48h to 4h through crisp ownership, technical troubleshooting, and cross-team escalation for GPU cluster provisioning at scale (100+ nodes, 99.9% reliability)",
                            size: 22,
                            font: "Calibri"
                        })
                    ],
                    spacing: { after: 60 }
                }),

                // Bullet 5
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "• Shipped proactive detection workflow (\"Project Mukti\") reducing mean time to mitigation by 75% and achieving negative time-to-detect (issues caught pre-customer) for Fortune 1 retailer during peak traffic; scaled to additional tier-1 accounts",
                            size: 22,
                            font: "Calibri"
                        })
                    ],
                    spacing: { after: 60 }
                }),

                // Bullet 6
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "• Drove control-plane KPIs to competitive parity/lead at scale (P90 VM provisioning ~25s at 99.9% reliability), enabling $16M+ annual contract revenue and avoiding discounts with strategic SaaS/data platform customers",
                            size: 22,
                            font: "Calibri"
                        })
                    ],
                    spacing: { after: 60 }
                }),

                // Bullet 7
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "• Created enterprise-scale operational playbooks: SKU launch playbook (reusable across generations), feature deployment playbook (platform-wide), and livesite recovery playbook reducing recovery time from 10h to 30min (20x improvement)",
                            size: 22,
                            font: "Calibri"
                        })
                    ],
                    spacing: { after: 150 }
                }),

                // Role 2 Title
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "Product Manager, Engineering Systems & Quality",
                            bold: true,
                            size: 22,
                            font: "Calibri"
                        })
                    ],
                    spacing: { after: 40 }
                }),

                // Role 2 Company
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "Microsoft, Azure | Redmond, WA | 2021 – 2022",
                            italics: true,
                            size: 22,
                            font: "Calibri"
                        })
                    ],
                    spacing: { after: 80 }
                }),

                // Role 2 Description
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "Owned product roadmap for internal engineering tools and validation systems supporting Azure's quality and developer productivity initiatives.",
                            size: 22,
                            font: "Calibri"
                        })
                    ],
                    spacing: { after: 80 }
                }),

                // Role 2 Bullet 1
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "• Led end-to-end Azure Quality Dashboard development (requirements, data feeds, UX), enabling organization-wide visibility into quality metrics and driving measurable adoption improvements across Azure repos",
                            size: 22,
                            font: "Calibri"
                        })
                    ],
                    spacing: { after: 60 }
                }),

                // Role 2 Bullet 2
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "• Coordinated S360 program across Azure Engineering System, DevDiv, and Azure Core to improve pre-production integration validation and inner-loop quality through strategic stakeholder alignment",
                            size: 22,
                            font: "Calibri"
                        })
                    ],
                    spacing: { after: 150 }
                }),

                // Role 3 Title
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "Data Science Technical Lead",
                            bold: true,
                            size: 22,
                            font: "Calibri"
                        })
                    ],
                    spacing: { after: 40 }
                }),

                // Role 3 Company
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "PACCAR Technical Center | Mt. Vernon, WA | 2017 – 2021",
                            italics: true,
                            size: 22,
                            font: "Calibri"
                        })
                    ],
                    spacing: { after: 80 }
                }),

                // Role 3 Description
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "Led technical programs for AI/analytics platforms and cross-functional initiatives supporting commercial vehicle product development.",
                            size: 22,
                            font: "Calibri"
                        })
                    ],
                    spacing: { after: 80 }
                }),

                // Role 3 Bullet 1
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "• Secured multi-million-dollar federal grant from U.S. Department of Energy, leading cross-functional proposal development across engineering, business, and government stakeholders for intelligent transportation systems program",
                            size: 22,
                            font: "Calibri"
                        })
                    ],
                    spacing: { after: 60 }
                }),

                // Role 3 Bullet 2
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "• Led AI/analytics programs for connected vehicles; built predictive models and experimentation frameworks that reduced classification error rates by 30% and informed product decisions",
                            size: 22,
                            font: "Calibri"
                        })
                    ],
                    spacing: { after: 200 }
                }),

                // Divider
                new Paragraph({
                    border: {
                        bottom: { style: BorderStyle.SINGLE, size: 6, color: "000000" }
                    },
                    spacing: { after: 200 }
                }),

                // Education Header
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "Education",
                            bold: true,
                            size: 24,
                            font: "Calibri"
                        })
                    ],
                    spacing: { before: 100, after: 100 }
                }),

                // Education 1
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "Graduate Certificate, Data Science",
                            bold: true,
                            size: 22,
                            font: "Calibri"
                        }),
                        new TextRun({
                            text: " — University of Washington (2020)",
                            size: 22,
                            font: "Calibri"
                        })
                    ],
                    spacing: { after: 60 }
                }),

                // Education 2
                new Paragraph({
                    children: [
                        new TextRun({
                            text: "M.S., Mechanical Engineering",
                            bold: true,
                            size: 22,
                            font: "Calibri"
                        }),
                        new TextRun({
                            text: " — University of Wisconsin–Madison (2013)",
                            size: 22,
                            font: "Calibri"
                        })
                    ]
                })
            ]
        }]
    });

    const buffer = await Packer.toBuffer(doc);
    fs.writeFileSync('/Users/varunr/projects/career/resumes/Varun_Ramesh_Anthropic_TPM_Launches_Resume.docx', buffer);
    console.log('DOCX generated successfully!');
}

generateResume().catch(console.error);

